function selectLinks($categoryl){
        $conn = openDBConnection();
        $sql = "SELECT address, name, date, status FROM link WHERE category = '$categoryl'";
        $result = mysqli_query($conn, $sql);
        $link = array();
        while ($row = $result->fetch_assoc()) {
            array_push($link, $row);
        }
        $result->free();
        dbConnectionClose($conn);
        return $link;
    }


